function requireSecret(env){const s=env&&env.SESSION_SECRET;if(typeof s!=="string"||s.length<8)throw new Error("SESSION_SECRET tidak dikonfigurasi (minimal 8 karakter)");if(s.length<32)console.warn("SESSION_SECRET kurang dari 32 karakter, segera rotasi");return s}
const safeEqual=(a,b)=>{const x=new TextEncoder().encode(String(a)),y=new TextEncoder().encode(String(b));if(x.length!==y.length)return false;let d=0;for(let i=0;i<x.length;i++)d|=x[i]^y[i];return d===0};
async function hashPassword(password,salt){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);return b64(await crypto.subtle.deriveBits({name:"PBKDF2",salt:unb64(salt),iterations:100000,hash:"SHA-256"},key,256));}
async function makeHash(password){const salt=b64(crypto.getRandomValues(new Uint8Array(16)));return {salt,hash:await hashPassword(password,salt)};}
async function token(payload,secret){const data=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const sig=b64(await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(data)));return data+"."+sig;}
async function verifyToken(t,secret){try{const [data,sig]=t.split(".");const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["verify"]);if(!await crypto.subtle.verify("HMAC",key,unb64(sig),new TextEncoder().encode(data)))return null;return JSON.parse(decodeURIComponent(escape(atob(data))));}catch{return null;}}
async function auth(req,env){try{const t=(req.headers.get("authorization")||"").replace(/^Bearer\s+/i,"");if(!t)return null;const p=await verifyToken(t,requireSecret(env));if(!p||!Number.isFinite(p.exp)||p.exp<Date.now()||!Number.isFinite(p.id))return null;const u=await env.DB.prepare("SELECT id,role,password_hash FROM users WHERE id=?").bind(p.id).first();if(!u||!p.v||!safeEqual(String(p.v),String(u.password_hash).slice(0,12)))return null;return {id:u.id,role:u.role,exp:p.exp}}catch(e){return null}}
