function findShift(id){for(var i=0;i<allShifts.length;i++)if(Number(allShifts[i].id)===Number(id))return allShifts[i];return null}
function paintShift(){var info=$("dashShiftInfo");if(!info)return;var sh=findShift(dashShiftId);if(sh)info.innerHTML="<b>"+escapeHtml(sh.name)+"</b><br>"+'<span class="muted">'+escapeHtml(sh.start_time)+"-"+escapeHtml(sh.end_time)+"</span>";else info.innerHTML='<span class="muted">Belum ada jadwal shift</span>'}
function shiftNow(){var now=new Date(Date.now()+7*3600*1000),hm=String(now.getUTCHours()).padStart(2,"0")+":"+String(now.getUTCMinutes()).padStart(2,"0");for(var i=0;i<allShifts.length;i++){var s=allShifts[i];if(!s.start_time||!s.end_time)continue;var w=s.start_time<=s.end_time?(hm>=s.start_time&&hm<=s.end_time):(hm>=s.start_time||hm<=s.end_time);if(w)return s}return null}
async function resolveShift(){var date=$("date")&&$("date").value||wibTodayClient();dateShifts=[];if(me&&me.role==="user"){try{var d=await api("/my-shift?date="+date);dateShifts=d.shifts||[]}catch(e){}}var sh=null;if(editMode&&editMode.shift_id)sh=findShift(editMode.shift_id);else if(lateMode&&lateMode.shift_id)sh=findShift(lateMode.shift_id);else{var pick=null;if(myAllowedShift){for(var i=0;i<dateShifts.length;i++)if(Number(dateShifts[i].id)===Number(myAllowedShift))pick=dateShifts[i]}if(!pick&&dateShifts.length)pick=dateShifts[0];if(pick)sh=findShift(pick.id);if(!sh&&myAllowedShift)sh=findShift(myAllowedShift);if(!sh)sh=shiftNow()}dashShiftId=sh?Number(sh.id):null;paintShift();fillSesi();loadShiftStatus()}
async function loadShifts(){try{let d=await api("/shifts");allShifts=d.shifts||[];renderDashShifts(allShifts);if(me&&me.role==="user")await resolveShift()}catch(e){}}
function renderDashShifts(list){var box=$('dashShiftRows');if(!box)return;var rows=(list||[]).map(function(x){
var name=escapeHtml(x.name);
return '<tr><td data-label="Shift">'+name+'</td><td data-label="Mulai"><input type="time" value="'+x.start_time+'" data-start="'+x.id+'" aria-label="Jam mulai '+name+'"></td><td data-label="Selesai"><input type="time" value="'+x.end_time+'" data-end="'+x.id+'" aria-label="Jam selesai '+name+'"></td><td data-label="Aksi"><button type="button" class="secondary" data-saveshift="'+x.id+'">Simpan</button></td></tr>'
}).join('');
box.innerHTML=rows||'<tr><td colspan="4" class="muted">Belum ada shift</td></tr>';
box.querySelectorAll('[data-saveshift]').forEach(function(b){b.onclick=function(){saveDashShift(b.getAttribute('data-saveshift'))}})}
async function saveDashShift(id){var btn=document.querySelector('#dashShiftRows [data-saveshift="'+id+'"]');if(!btn)return;var tr=btn.closest("tr"),msg=$("dashShiftMsg");if(!tr)return;var name=tr.children[0].textContent.trim(),st=tr.querySelector("[data-start]").value,en=tr.querySelector("[data-end]").value;if(!st||!en){if(msg)msg.textContent="Jam mulai dan selesai wajib diisi";return}if(st===en){if(msg)msg.textContent="Jam mulai dan selesai tidak boleh sama";return}btn.disabled=true;if(msg)msg.textContent="Menyimpan...";try{await api("/admin/shifts",{method:"POST",body:JSON.stringify({name:name,start_time:st,end_time:en})});if(msg)msg.textContent="Jam "+name+" tersimpan";notify("Jam shift diperbarui");await loadShifts();loadNotif()}catch(e){if(msg)msg.textContent=e.message}finally{btn.disabled=false}}
function fillSesi(){var sh=findShift(dashShiftId),win=[["",""],["",""],["",""]];if(sh&&/^\\d{2}:\\d{2}$/.test(sh.start_time)&&/^\\d{2}:\\d{2}$/.test(sh.end_time)){var mins=function(x){return Number(x.slice(0,2))*60+Number(x.slice(3,5))};var sm=mins(sh.start_time),raw=mins(sh.end_time),em=raw<=sm?raw+1440:raw;var fmt=function(x){return String(Math.floor(x/60)%24).padStart(2,"0")+":"+String(x%60).padStart(2,"0")};win=[[sm+60,sm+180],[sm+240,sm+360],[sm+420,em]].map(function(w){return [fmt(w[0]),fmt(w[1])]})}var opts=[];for(var n=1;n<=3;n++)opts.push('<option value="'+n+'">Sesi '+n+(win[n-1][0]?' ('+win[n-1][0]+"-"+win[n-1][1]+')':'')+'</option>');$("sesiSelect").innerHTML=opts.join("");updateFormTitle()}
$("gotoShiftEditor").onclick=function(){adminTab("ringkasan");var p=$("dashShiftPanel");if(!p)return;try{p.scrollIntoView({block:"start"})}catch(e){}};

var schedRows=[],schedOff=[],schedUsers=[],schedShifts=[],schedCellUser=null,schedCellDate="";
var SCHED_MONTHS=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
var SCHED_WEEK=["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"];
var SCHED_WEEK_SHORT=["Mg","Sn","Sl","Rb","Km","Jm","Sb"];
var SCHED_CODE={1:"P",2:"S",3:"M"};
function schedNextDate(d,n){var t=new Date(d+"T00:00:00Z");t.setUTCDate(t.getUTCDate()+n);return t.toISOString().slice(0,10)}
function schedMonthDays(month){var y=Number(month.slice(0,4)),m=Number(month.slice(5,7));return new Date(Date.UTC(y,m,0)).getUTCDate()}
function schedMonthText(month){var p=String(month).split("-");return SCHED_MONTHS[Number(p[1])-1]+" "+p[0]}
function schedDateText(date){var p=String(date).split("-");return Number(p[2])+" "+SCHED_MONTHS[Number(p[1])-1]+" "+p[0]}
function schedCode(s){return SCHED_CODE[Number(s.id)]||String(s.name).charAt(0).toUpperCase()}
function schedShiftName(id){for(var i=0;i<schedShifts.length;i++)if(Number(schedShifts[i].id)===Number(id))return schedShifts[i].name;return ""}
function schedCellHtml(u,date,sids,off){
var codes=[],names=[];
sids.slice().sort(function(a,b){return a-b}).forEach(function(id){
var found=null;for(var i=0;i<schedShifts.length;i++)if(Number(schedShifts[i].id)===id)found=schedShifts[i];
if(found){codes.push(schedCode(found));names.push(found.name)}else{codes.push("?");names.push("Shift "+id)}
});
var text=off?"O":(codes.length?codes.join("+"):"-");
var cls="sched-cell"+(off?" is-off":(codes.length?"":" is-empty"));
var label=u.name+", "+schedDateText(date)+": "+(off?"Libur":(names.length?names.join(", "):"belum dijadwalkan"));
return '<td><button type="button" class="'+cls+'" data-sched-cell="1" data-user="'+u.id+'" data-date="'+date+'" aria-haspopup="dialog" aria-label="'+escapeHtml(label)+'">'+text+"</button></td>";
}
async function loadSched(){
var mmsg=$("schedMonthMsg"),body=$("schedMonthBody");
if($("schedMonth")&&!$("schedMonth").value)$("schedMonth").value=wibTodayClient().slice(0,7);
try{
var u=await api("/admin/users");
schedUsers=(u.users||[]).filter(function(x){return x.role==="user"}).sort(function(a,b){var d=(Number(a.sort_order)||0)-(Number(b.sort_order)||0);return d!==0?d:(a.name<b.name?-1:a.name>b.name?1:0)});
await loadSchedMonth();
}catch(e){
if(mmsg)mmsg.textContent=e.message;
if(body){var m=$("schedMonth").value||wibTodayClient().slice(0,7);body.innerHTML='<tr><td class="muted" colspan="'+(schedMonthDays(m)+1)+'">Jadwal gagal dimuat. Pilih bulan untuk mencoba lagi.</td></tr>'}
applySchedView();renderSchedMobile();
}
}
async function loadSchedMonth(){
var month=$("schedMonth").value||wibTodayClient().slice(0,7);
var start=month+"-01";
var days=schedMonthDays(month);
var res=await api("/admin/schedule?start="+encodeURIComponent(start)+"&days="+days);
res.start=start;res.days=days;
schedRows=res.rows||[];schedOff=res.off||[];schedShifts=res.shifts||[];
renderSchedMonth(res);
}
