async function exportWorkbook(list,title,filename){
 if(!list||!list.length)throw new Error("Tidak ada data untuk diekspor");
 await loadExcelJS();
 var wb=new ExcelJS.Workbook();wb.creator="DCM Menara Pertiwi";
 var groups={},order=[];
 list.forEach(function(r){var k=r.date+"|"+r.kind;if(!groups[k]){groups[k]=[];order.push(k)}groups[k].push(r)});
 order.sort();
 var CAP=60,plan=order.slice(0,CAP),skipped=order.length-plan.length;
 var fcache={};
 for(var i=0;i<plan.length;i++){var kind=groups[plan[i]][0].kind;if(!fcache[kind])fcache[kind]=await xlFields(kind)}
 plan.forEach(function(k){
   var recs=groups[k],kind=recs[0].kind,date=recs[0].date;
   if(kind==="Chiller York Centrifugal")xlChillerSheet(wb,kind,date,recs,fcache[kind]);
   else xlLogSheet(wb,kind,date,recs,fcache[kind]);
 });
 if(plan.length>1)xlRekap(wb,list,title,skipped);
 var buf=await wb.xlsx.writeBuffer();
 var blob=new Blob([buf],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
 var a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();
 setTimeout(function(){URL.revokeObjectURL(a.href);if(a.parentNode)a.parentNode.removeChild(a)},5000);
}
